window.HYDRO_DEMO_QUESTIONS.push(...[{"id":"V2-C2-D101-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle d'apports successifs utilise \\(u_n=\\frac{120}{n(n+1)}\\) litres, n≥1. Quel est le cumul total et la quantité restant à apporter après N étapes ?","a":["Total 120 L ; reste \\(120/N\\) L.","Total 120 L ; reste \\(120/(N+1)\\) L.","Total 60 L ; reste \\(120/(N+1)\\) L.","Cumul divergent, car u_n est équivalent à 120/n."],"correct":1,"why":"La décomposition 120(1/n-1/(n+1)) donne S_N=120(1-1/(N+1)).","active":true,"family":"V2-C2-D101"},{"id":"V2-C2-D101-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(u_n=\\frac{6}{(n+1)(n+2)}\\) pour n≥1. Quelle affirmation concernant la série est exacte ?","a":["Elle converge vers 3, et son reste après N termes vaut \\(6/(N+2)\\).","Elle converge vers 6, et son reste vaut \\(6/(N+1)\\).","Elle converge vers 2, car le premier terme vaut 1.","Elle diverge comme la série harmonique."],"correct":0,"why":"La décomposition 6/(n+1)-6/(n+2) donne S_N=3-6/(N+2).","active":true,"family":"V2-C2-D101"},{"id":"V2-C2-D101-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une série d'infiltration a pour terme \\(u_n=\\frac{90}{n(n+1)}\\) L. À partir de combien d'étapes le volume restant est-il inférieur ou égal à 3 L ?","a":["30 étapes.","28 étapes.","3 étapes.","29 étapes."],"correct":3,"why":"Le reste télescopique vaut 90/(N+1). Résoudre N+1≥30.","active":true,"family":"V2-C2-D101"},{"id":"V2-C2-D102-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour des contributions positives \\(u_n=n^2/4^n\\), quel critère permet de conclure correctement sur la série \\(\\sum u_n\\) ?","a":["D'Alembert, car le rapport tend vers 4 : divergence.","Riemann, car u_n est équivalent à n² : divergence.","D'Alembert, car \\(u_{n+1}/u_n\\to1/4<1\\) : convergence.","Le seul fait que u_n tende vers zéro suffit à prouver la convergence."],"correct":2,"why":"Le rapport vaut (n+1)²/(4n²), de limite 1/4.","active":true,"family":"V2-C2-D102"},{"id":"V2-C2-D102-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Les corrections successives d'un modèle de débit valent \\(v_n=\\frac{3^n}{n!}\\). Quelle conclusion découle du critère du rapport ?","a":["Elle diverge, car le rapport tend vers 3.","Elle diverge, car le numérateur augmente exponentiellement.","La série converge, car \\(v_{n+1}/v_n=3/(n+1)\\to0\\).","Le critère ne permet pas de conclure, car le rapport tend vers 1."],"correct":2,"why":"La factorielle introduit un facteur n+1 au dénominateur du rapport.","active":true,"family":"V2-C2-D102"},{"id":"V2-C2-D102-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Soient \\(u_n=1/n\\) et \\(v_n=1/n^2\\) pour n≥1. Les deux rapports de termes consécutifs tendent vers 1. Quelle interprétation est correcte ?","a":["Les deux séries convergent puisque leurs rapports ne dépassent pas 1.","Le critère de D'Alembert est indécis ; Riemann distingue divergence de la première et convergence de la seconde.","Les deux séries divergent puisque la limite du rapport vaut 1.","Les deux séries ont nécessairement la même nature."],"correct":1,"why":"Le cas limite L=1 ne permet aucune conclusion via D'Alembert.","active":true,"family":"V2-C2-D102"},{"id":"V2-C2-F101-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Soit une série de termes positifs \\(\\sum_{n=1}^{\\infty}u_n\\). Quelle expression définit sa somme partielle d'ordre N ?","a":["\\(S_N=u_N-u_1\\)","\\(S_N=\\sum_{n=N+1}^{\\infty}u_n\\)","\\(S_N=u_1+u_2+\\cdots+u_N\\)","\\(S_N=Nu_N\\)"],"correct":2,"why":"Une somme partielle additionne exactement les N premiers termes.","active":true,"family":"V2-C2-F101"},{"id":"V2-C2-F101-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une station hydrologique enregistre des précipitations journalières \\(p_1,p_2,\\ldots\\), exprimées en mm. Quelle grandeur représente \\(\\sum_{k=1}^{30}p_k\\) ?","a":["La précipitation du trentième jour.","Le cumul des précipitations durant les 30 premiers jours.","La moyenne journalière sur 30 jours.","Le cumul des précipitations après le trentième jour."],"correct":1,"why":"La somme partielle représente le cumul jusqu'à l'indice 30.","active":true,"family":"V2-C2-F101"},{"id":"V2-C2-F101-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant confond le reste et la somme partielle d'une série convergente. Quelle relation définit correctement le reste \\(R_N\\) si S est la somme totale ?","a":["\\(R_N=S-S_N\\)","\\(R_N=S_N-S\\)","\\(R_N=u_N\\)","\\(R_N=S+S_N\\)"],"correct":0,"why":"Le reste est la somme des termes qui n'ont pas été inclus dans S_N.","active":true,"family":"V2-C2-F101"},{"id":"V2-C2-F102-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Quelle condition est nécessaire, mais non suffisante, pour qu'une série numérique \\(\\sum u_n\\) converge ?","a":["\\(u_n>0\\) pour tout n.","\\(\\lim_{n\\to\\infty}S_n=0\\)","\\(u_n=0\\) pour tout n suffisamment grand.","\\(\\lim_{n\\to\\infty}u_n=0\\)"],"correct":3,"why":"La convergence entraîne la différence de sommes partielles tendant vers zéro.","active":true,"family":"V2-C2-F102"},{"id":"V2-C2-F102-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant conclut que \\(\\sum_{n=1}^{\\infty}1/n\\) converge parce que \\(1/n\\to0\\). Pourquoi ce raisonnement est-il incorrect ?","a":["La suite 1/n ne tend pas vers zéro.","La série harmonique est une série géométrique de raison 1/2.","Toute série à termes strictement positifs converge.","La convergence du terme général vers zéro ne suffit pas à garantir celle de la série."],"correct":3,"why":"La série harmonique fournit un contre-exemple à la suffisance de la condition.","active":true,"family":"V2-C2-F102"},{"id":"V2-C2-F102-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour des apports d'eau modélisés par \\(u_n=2+1/n\\) litres, que peut-on déduire sur la convergence de la série des apports ?","a":["Elle converge, car chaque terme est fini.","Elle converge, car les termes décroissent.","Elle diverge, car les termes tendent vers 2 et non vers zéro.","Elle converge vers 2, limite du terme général."],"correct":2,"why":"Une série convergente doit avoir un terme général tendant vers zéro.","active":true,"family":"V2-C2-F102"},{"id":"V2-C2-M101-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une cuve reçoit une première quantité de 60 L, puis chaque apport vaut les deux tiers du précédent. Quel est le volume cumulé théorique si le processus se poursuit indéfiniment ?","a":["90 L.","180 L.","120 L.","150 L."],"correct":1,"why":"La somme géométrique vaut 60/(1-2/3).","active":true,"family":"V2-C2-M101"},{"id":"V2-C2-M101-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(S=\\sum_{n=0}^{\\infty}24(3/4)^n\\). Quel calcul justifie sa convergence et donne sa somme exacte ?","a":["\\(S=24/(1-3/4)=96\\).","\\(S=24/(3/4)=32\\).","\\(S=24(1-3/4)=6\\).","\\(S=24/(1+3/4)=96/7\\)."],"correct":0,"why":"La raison est strictement comprise entre 0 et 1 ; la somme vaut le premier terme divisé par 1-q.","active":true,"family":"V2-C2-M101"},{"id":"V2-C2-M101-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Un dispositif d'infiltration reçoit 100 L à l'étape initiale. Les apports suivants sont divisés par deux à chaque étape. Quelle quantité totale est apportée après l'étape initiale, sans la compter ?","a":["100 L.","200 L.","50 L.","150 L."],"correct":0,"why":"La queue commence par 50 et sa somme vaut 50/(1-1/2)=100.","active":true,"family":"V2-C2-M101"},{"id":"V2-C2-M102-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour la série \\(\\sum_{n=1}^{\\infty}(2/5)^n\\), pourquoi le calcul de la somme diffère-t-il de celui d'une série commençant à n=0 ?","a":["Le changement d'indice modifie la raison, qui devient 5/2.","La série ne converge plus puisque le premier terme n'est pas 1.","Le premier terme vaut toujours 1 quelle que soit la borne inférieure.","Le terme d'indice zéro est absent : la somme vaut \\((2/5)/(1-2/5)\\)."],"correct":3,"why":"La raison ne change pas, mais le premier terme vaut 2/5.","active":true,"family":"V2-C2-M102"},{"id":"V2-C2-M102-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Des pertes d'eau successives sont données par \\(L_n=40(1/4)^n\\) litres pour n≥1. Quel est le cumul de ces pertes ?","a":["\\(160/3\\) L.","10 L.","\\(40/3\\) L.","30 L."],"correct":2,"why":"Le premier terme est 10 et la raison est 1/4 : 10/(3/4)=40/3.","active":true,"family":"V2-C2-M102"},{"id":"V2-C2-M102-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"On calcule \\(\\sum_{n=1}^{\\infty}(3/5)^n\\) et un collègue annonce 5/2. Quelle correction convient ?","a":["Ajouter le terme d'indice zéro : la somme correcte est 7/2.","Retrancher le terme d'indice zéro : la somme correcte est 3/2.","Conserver 5/2, puisque le rang initial ne joue aucun rôle.","Inverser la valeur 5/2, ce qui donne 2/5."],"correct":1,"why":"La somme à partir de zéro vaut 5/2 et comprend un terme égal à 1.","active":true,"family":"V2-C2-M102"},{"id":"V2-C2-F203-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une série à termes positifs a des sommes partielles \\(S_{N}\\). Quelle propriété de cette suite résulte du signe des termes ?","a":["Elle est croissante au sens large.","Elle est décroissante.","Elle est nécessairement bornée.","Elle converge nécessairement vers zéro."],"correct":0,"why":"\\(S_{N+1}\\)-\\(S_{N}\\)=\\(u_{N+1}\\)≥0.","active":true,"family":"V2-C2-F203"},{"id":"V2-C2-F203-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un cumul de pluie ne diminue jamais au cours de l'observation. Quelle propriété des contributions journalières explique ce comportement ?","a":["Elles sont toutes inférieures à 1 mm.","Leur somme est nécessairement finie.","Elles sont constantes.","Elles sont toutes non négatives."],"correct":3,"why":"L'ajout d'une contribution positive ou nulle préserve l'ordre du cumul.","active":true,"family":"V2-C2-F203"},{"id":"V2-C2-F203-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une série de termes non négatifs a \\(S_{8}\\)=12 et \\(S_{9}\\)=14. Quelle affirmation est certaine ?","a":["Le neuvième terme vaut 26.","La somme totale vaut exactement 14.","Le neuvième terme vaut 2 et \\(S_{10}\\)≥14.","\\(S_{10}\\) est nécessairement inférieur à 14."],"correct":2,"why":"Le terme ajouté est 14-12 ; le cumul reste croissant.","active":true,"family":"V2-C2-F203"},{"id":"V2-C2-F204-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour une série à termes positifs, quelle condition sur ses sommes partielles est équivalente à la convergence ?","a":["Elles sont minorées par zéro.","Elles sont majorées par une constante finie.","Elles sont strictement croissantes.","Leur premier terme est inférieur à 1."],"correct":1,"why":"La suite croissante des sommes partielles converge si et seulement si elle est majorée.","active":true,"family":"V2-C2-F204"},{"id":"V2-C2-F204-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un modèle d'apports positifs donne des cumuls \\(S_{N}\\) toujours inférieurs ou égaux à 500 L. Que peut-on en déduire sur le cumul infini ?","a":["Il est nécessairement égal à 500 L.","Il existe et ne dépasse pas 500 L.","Il diverge car les cumuls sont croissants.","Il vaut zéro car les apports tendent vers zéro."],"correct":1,"why":"La monotonie et la majoration assurent la convergence.","active":true,"family":"V2-C2-F204"},{"id":"V2-C2-F204-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"On sait que la suite des sommes partielles d'une série positive tend vers +∞. Quel diagnostic est exact ?","a":["La série diverge vers +∞.","Elle converge vers un réel positif.","Elle converge vers zéro.","Sa nature dépend de la parité de N."],"correct":0,"why":"Une série converge lorsque ses sommes partielles ont une limite finie.","active":true,"family":"V2-C2-F204"},{"id":"V2-C2-F205-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Soit une série géométrique de raison q et de premier terme non nul. Quelle condition assure sa convergence absolue ?","a":["\\(q\\le1\\)","\\(q>0\\)","\\(\\vert q\\vert>1\\)","\\(\\vert q\\vert<1\\)"],"correct":3,"why":"Le terme q^n décroît en module et les sommes géométriques convergent lorsque le module de q est inférieur à 1.","active":true,"family":"V2-C2-F205"},{"id":"V2-C2-F205-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Des contributions positives vérifient \\(u_{n+1}\\)=0,8\\(u_{n}\\). Quelle propriété permet de conclure sur leur cumul infini ?","a":["La raison est positive : le cumul diverge.","Chaque terme est inférieur au précédent : cela suffit pour toute série.","La raison 0,8 est strictement inférieure à 1 : le cumul converge.","La raison doit être supérieure à 1 pour converger."],"correct":2,"why":"Le critère des séries géométriques s'applique.","active":true,"family":"V2-C2-F205"},{"id":"V2-C2-F205-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un modèle donne 10 L à chaque étape, soit une série géométrique de raison 1. Pourquoi son cumul n'est-il pas fini ?","a":["La raison est strictement inférieure à 1.","Le premier terme n'est pas égal à 1.","La raison égale 1 et les termes ne tendent pas vers zéro.","Les termes ne sont pas strictement positifs."],"correct":2,"why":"Les sommes partielles valent 10N et tendent vers +∞.","active":true,"family":"V2-C2-F205"},{"id":"V2-C2-F206-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour p réel, à quelle condition la série de Riemann \\(\\sum_{n=1}^{\\infty}1/n^p\\) converge-t-elle ?","a":["\\(p\\ge1\\)","\\(p>1\\)","\\(p>0\\)","\\(p<1\\)"],"correct":1,"why":"Le seuil de convergence est strict : p=1 donne la série harmonique divergente.","active":true,"family":"V2-C2-F206"},{"id":"V2-C2-F206-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Deux modèles ont pour apports \\(u_n=1/n\\) et \\(v_n=1/n^2\\). Quelle différence de nature est correcte ?","a":["La série des \\(u_{n}\\) diverge et celle des \\(v_{n}\\) converge.","Les deux convergent car les termes tendent vers zéro.","Les deux divergent car les termes sont positifs.","La première converge et la seconde diverge."],"correct":0,"why":"Le critère de Riemann distingue les exposants 1 et 2.","active":true,"family":"V2-C2-F206"},{"id":"V2-C2-F206-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un exposant p=0,8 apparaît dans \\(\\sum 1/n^p\\). Un étudiant invoque p>0 pour conclure à la convergence. Quelle correction faut-il apporter ?","a":["Il suffit que p>0, donc le raisonnement est juste.","Il faut p<0 pour converger.","Il faut p=1 exactement.","La convergence exige p>1 ; ici la série diverge."],"correct":3,"why":"Une suite tendant vers zéro ne définit pas nécessairement une série convergente.","active":true,"family":"V2-C2-F206"},{"id":"V2-C2-F207-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour deux séries de termes positifs vérifiant \\(0\\le u_n\\le v_n\\) à partir d'un certain rang, quelle implication est valide ?","a":["La convergence des \\(u_{n}\\) entraîne celle des \\(v_{n}\\).","La divergence des \\(v_{n}\\) entraîne celle des \\(u_{n}\\).","Les deux séries ont toujours la même nature.","La convergence de la série des \\(v_{n}\\) entraîne celle des \\(u_{n}\\)."],"correct":3,"why":"La comparaison par une série positive convergente majore les sommes partielles.","active":true,"family":"V2-C2-F207"},{"id":"V2-C2-F207-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Des apports positifs sont majorés par les termes d'une série dont le cumul total est fini. Que peut-on conclure ?","a":["Leur propre cumul diverge.","Leur cumul égale celui des majorants.","Leur propre cumul est fini.","Leur cumul vaut nécessairement zéro."],"correct":2,"why":"La comparaison assure la convergence, pas l'égalité des sommes.","active":true,"family":"V2-C2-F207"},{"id":"V2-C2-F207-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"On sait que \\(0\\le u_n\\le1/n\\). Pourquoi ne peut-on pas conclure directement que la série des \\(u_{n}\\) diverge ?","a":["La série harmonique converge.","Une majoration par une série divergente est insuffisante.","La comparaison exige des termes négatifs.","La majoration entraîne toujours la convergence."],"correct":1,"why":"Par exemple, 1/n² est majorée par 1/n mais sa série converge.","active":true,"family":"V2-C2-F207"},{"id":"V2-C2-F208-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour deux suites positives telles que \\(u_n\\sim v_n\\), que garantit le critère d'équivalence pour les séries associées ?","a":["Elles sont de même nature.","Elles ont nécessairement la même somme.","Leurs termes sont égaux pour tout n.","Elles convergent toutes les deux dans tous les cas."],"correct":0,"why":"Le rapport tend vers 1 et fournit des comparaisons à partir d'un certain rang.","active":true,"family":"V2-C2-F208"},{"id":"V2-C2-F208-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un modèle vérifie \\(u_n\\sim3/n^2\\). Quelle conclusion est justifiée ?","a":["La série des apports converge.","Elle diverge car 3>1.","Sa somme vaut exactement 3.","Elle ne converge que si \\(u_{n}\\)=3/n² pour tout n."],"correct":0,"why":"La série de Riemann d'exposant 2 converge.","active":true,"family":"V2-C2-F208"},{"id":"V2-C2-F208-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"On sait que \\(u_n\\sim2/n\\). Quelle conséquence est rigoureuse ?","a":["Le cumul vaut 2.","Les apports ne tendent pas vers zéro.","La série est géométrique de raison 2.","Le cumul infini diverge."],"correct":3,"why":"La série est de même nature que la série harmonique.","active":true,"family":"V2-C2-F208"},{"id":"V2-C2-F209-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour une suite positive, quel rapport est étudié dans le critère de D'Alembert ?","a":["\\(u_n/n\\)","\\(S_{n+1}/S_n\\)","\\(u_{n+1}/u_n\\)","\\(u_{n+1}-u_n\\)"],"correct":2,"why":"Le critère porte sur le rapport de deux termes consécutifs.","active":true,"family":"V2-C2-F209"},{"id":"V2-C2-F209-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour une série positive, le rapport des termes consécutifs tend vers 0,6. Quelle conclusion donne le critère de D'Alembert ?","a":["La série diverge.","La série converge.","Le critère est indécis.","La somme vaut nécessairement 0,6."],"correct":1,"why":"La limite du rapport est strictement inférieure à 1.","active":true,"family":"V2-C2-F209"},{"id":"V2-C2-F209-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour une série positive, le rapport tend vers 1. Que permet de conclure D'Alembert seul ?","a":["La série converge toujours.","Aucune conclusion générale sur la convergence.","La série diverge toujours.","La somme vaut 1."],"correct":1,"why":"Le cas limite 1 nécessite un autre critère.","active":true,"family":"V2-C2-F209"},{"id":"V2-C2-F210-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Quel terme est étudié par le critère de Cauchy pour une série positive ?","a":["\\(\\sqrt[n]{u_n}\\)","\\(u_n^{n}\\)","\\(u_n/u_{n+1}\\)","\\(\\sqrt{S_n}\\)"],"correct":0,"why":"Le critère porte sur la racine n-ième du terme général.","active":true,"family":"V2-C2-F210"},{"id":"V2-C2-F210-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"On observe que \\(\\sqrt[n]{u_n}\\to0,7\\). Quelle nature de la série des \\(u_{n}\\) en découle ?","a":["Divergente.","Indéterminée car 0,7>0.","Somme exactement égale à 0,7.","Convergente."],"correct":3,"why":"La limite de la racine est strictement inférieure à 1.","active":true,"family":"V2-C2-F210"},{"id":"V2-C2-F210-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Le critère de Cauchy donne une limite 1,2. Quel diagnostic est correct ?","a":["Elle converge car 1,2 est fini.","La somme vaut 1,2.","La série diverge.","Le critère est toujours indécis."],"correct":2,"why":"Une limite strictement supérieure à 1 entraîne la divergence.","active":true,"family":"V2-C2-F210"},{"id":"V2-C2-F211-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Quelle identité permet de rendre télescopique la somme \\(\\sum_{n=1}^N1/(n(n+1))\\) ?","a":["\\(1/(n(n+1))=1/n+1/(n+1)\\)","\\(1/(n(n+1))=1/n^2\\)","\\(1/(n(n+1))=1/n-1/(n+1)\\)","\\(1/(n(n+1))=1/(2n+1)\\)"],"correct":2,"why":"Mettre les deux fractions au même dénominateur.","active":true,"family":"V2-C2-F211"},{"id":"V2-C2-F211-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant additionne des termes de la forme \\(u_n=a_n-a_{n+1}\\). Quel phénomène simplifie la somme partielle ?","a":["Tous les termes s'annulent, y compris les extrémités.","Les termes intermédiaires se compensent et il reste \\(a_{1}\\)-\\(a_{N+1}\\).","La somme se transforme en produit.","La somme vaut toujours \\(a_{N}\\)."],"correct":1,"why":"L'écriture successive montre les annulations internes.","active":true,"family":"V2-C2-F211"},{"id":"V2-C2-F211-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour \\(u_n=1/n-1/(n+1)\\), que vaut \\(S_{2}\\) ?","a":["\\(2/3\\)","\\(1/3\\)","\\(3/2\\)","\\(1/2\\)"],"correct":0,"why":"\\(S_{2}\\)=(1-1/2)+(1/2-1/3)=2/3.","active":true,"family":"V2-C2-F211"},{"id":"V2-C2-F212-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une suite est croissante et majorée. Quelle conclusion est assurée ?","a":["Elle est nécessairement constante.","Elle tend nécessairement vers zéro.","Elle diverge vers +∞.","Elle converge vers une limite finie."],"correct":3,"why":"Théorème de convergence monotone.","active":true,"family":"V2-C2-F212"},{"id":"V2-C2-F212-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Les volumes stockés \\(V_{n}\\) augmentent chaque jour, sans dépasser la capacité K. Que peut-on déduire mathématiquement ?","a":["La suite converge forcément vers K.","Elle décroît vers zéro.","Elle ne peut pas converger si elle est croissante.","La suite converge vers une limite inférieure ou égale à K."],"correct":3,"why":"Une suite croissante et majorée converge, sans nécessairement atteindre son majorant.","active":true,"family":"V2-C2-F212"},{"id":"V2-C2-F212-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une suite décroissante possède un minorant fini. Quelle affirmation est exacte ?","a":["Elle tend nécessairement vers -∞.","Elle oscille entre deux limites.","Elle converge vers une limite finie.","Elle converge forcément vers son premier terme."],"correct":2,"why":"Le théorème de convergence monotone vaut aussi pour une suite décroissante minorée.","active":true,"family":"V2-C2-F212"},{"id":"V2-C2-F213-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour une suite arithmétique vérifiant \\(u_{n+1}\\)=\\(u_{n}\\)+r, que représente r ?","a":["Le quotient de deux termes consécutifs.","La différence constante de deux termes consécutifs.","La limite de la suite.","Le premier terme nécessairement."],"correct":1,"why":"La relation de récurrence se réécrit \\(u_{n+1}\\)-\\(u_{n}\\)=r.","active":true,"family":"V2-C2-F213"},{"id":"V2-C2-F213-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une station relève une hausse constante de 3 mm d'une grandeur à chaque jour. Quel modèle de suite représente cette évolution ?","a":["Arithmétique de raison 3.","Géométrique de raison 3.","Arithmétique de raison 1/3.","Constante égale à 3."],"correct":0,"why":"L'accroissement absolu est constant.","active":true,"family":"V2-C2-F213"},{"id":"V2-C2-F213-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une série de mesures a \\(u_{1}\\)=8, \\(u_{2}\\)=11, \\(u_{3}\\)=14. Quelle raison arithmétique est compatible avec ces observations ?","a":["3.","11/8.","8.","6."],"correct":0,"why":"Les différences successives sont 3.","active":true,"family":"V2-C2-F213"},{"id":"V2-C2-F214-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Pour une suite géométrique de premier terme positif, quelle caractéristique est constante ?","a":["La différence \\(u_{n+1}\\)-\\(u_{n}\\).","Le terme général.","La somme partielle.","Le rapport \\(u_{n+1}\\)/\\(u_{n}\\) si les termes sont non nuls."],"correct":3,"why":"Chaque terme est obtenu par multiplication par la même raison.","active":true,"family":"V2-C2-F214"},{"id":"V2-C2-F214-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un réservoir conserve 75 % de son volume à chaque étape. Quel modèle discret décrit le volume restant ?","a":["Suite arithmétique de raison -0,75.","Suite géométrique de raison 0,25.","Suite géométrique de raison 0,75.","Suite arithmétique de raison 75."],"correct":2,"why":"Le volume suivant vaut 0,75 fois le précédent.","active":true,"family":"V2-C2-F214"},{"id":"V2-C2-F214-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"On observe \\(u_{0}\\)=100, \\(u_{1}\\)=40 et \\(u_{2}\\)=16. Quelle raison géométrique est compatible avec ces valeurs ?","a":["0,6.","0,4.","2,5.","0,16."],"correct":1,"why":"Les deux rapports 40/100 et 16/40 valent 0,4.","active":true,"family":"V2-C2-F214"},{"id":"V2-C2-F215-V1","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une suite réelle possède une limite finie. Quelle propriété est nécessaire ?","a":["Elle est strictement croissante.","Elle est bornée.","Elle est géométrique.","Elle est de limite zéro."],"correct":1,"why":"Les termes sont proches de la limite après un certain rang, et les premiers sont en nombre fini.","active":true,"family":"V2-C2-F215"},{"id":"V2-C2-F215-V2","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Un étudiant affirme qu'une suite bornée converge toujours. Quel contre-exemple réfute son affirmation ?","a":["\\(u_n=(-1)^n\\).","\\(u_n=1/n\\).","\\(u_n=2\\).","\\(u_n=(1/2)^n\\)."],"correct":0,"why":"La suite alternant -1 et 1 est bornée mais n'a pas de limite.","active":true,"family":"V2-C2-F215"},{"id":"V2-C2-F215-V3","chapter":2,"level":"facile","usage":"ENTRAINEMENT","q":"Une suite positive est non bornée. Peut-elle converger vers une limite réelle finie ?","a":["Oui, si ses termes sont tous positifs.","Oui, si elle est croissante.","Oui, si son premier terme vaut zéro.","Non, une suite convergente est bornée."],"correct":3,"why":"La bornitude est nécessaire à la convergence finie.","active":true,"family":"V2-C2-F215"},{"id":"V2-C2-M203-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(u_n=3/(n^2+5)\\), n≥1. Quelle comparaison suffit à démontrer la convergence de sa série ?","a":["\\(u_n\\le3/n\\) et l'harmonique diverge.","\\(u_n\\ge0\\), ce qui suffit seul.","\\(0\\le u_n\\le3/n^2\\) et la série majorante converge.","\\(u_n\\le3\\), donc le cumul est fini."],"correct":2,"why":"Comparer à une série de Riemann d'exposant 2.","active":true,"family":"V2-C2-M203"},{"id":"V2-C2-M203-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Des pertes résiduelles valent \\(p_n=8/(n^3+2n)\\) L. Quel majorant de type Riemann garantit un cumul fini ?","a":["\\(8/n\\)","\\(8\\)","\\(8/n^3\\)","\\(8n\\)"],"correct":2,"why":"Le dénominateur est au moins n³.","active":true,"family":"V2-C2-M203"},{"id":"V2-C2-M203-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"On cherche un critère pour \\(u_n=1/(n^2+1)\\). Un étudiant compare à 1/n et s'arrête. Quelle comparaison plus utile doit-il employer ?","a":["\\(u_n\\ge1/n\\), série divergente.","\\(u_n\\le1/n^2\\), série convergente.","\\(u_n\\ge1\\), série divergente.","\\(u_n\\le1/n\\), ce qui prouve la divergence."],"correct":1,"why":"La majoration par une série convergente donne le résultat.","active":true,"family":"V2-C2-M203"},{"id":"V2-C2-M204-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(u_n=(n+2)/(n^2+1)\\). Quelle équivalence permet de déterminer la nature de la série ?","a":["\\(u_n\\sim1/n\\) ; divergence.","\\(u_n\\sim1/n^2\\) ; convergence.","\\(u_n\\sim n\\) ; divergence.","\\(u_n\\sim2/n^2\\) ; convergence."],"correct":0,"why":"Le numérateur a degré 1 et le dénominateur degré 2.","active":true,"family":"V2-C2-M204"},{"id":"V2-C2-M204-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Les apports vérifient \\(u_n=(2n+1)/(n^3+4)\\). Quel diagnostic repose sur le terme dominant ?","a":["\\(u_n\\sim2/n\\), donc divergence.","\\(u_n\\sim1/n^3\\), donc la somme vaut 1.","\\(u_n\\sim2n\\), donc divergence.","\\(u_n\\sim2/n^2\\), donc convergence."],"correct":3,"why":"Diviser par les termes dominants.","active":true,"family":"V2-C2-M204"},{"id":"V2-C2-M204-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(u_n=(3n^2+1)/(n^3+n)\\), quelle comparaison asymptotique est correcte ?","a":["\\(u_n\\sim3/n^2\\), donc convergence.","\\(u_n\\sim1/n^3\\), donc convergence.","\\(u_n\\sim3\\), donc les termes ne tendent pas vers zéro.","\\(u_n\\sim3/n\\), donc divergence."],"correct":3,"why":"Le rapport des degrés donne une décroissance en 1/n.","active":true,"family":"V2-C2-M204"},{"id":"V2-C2-M205-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(u_n=n/3^n\\), quelle limite du rapport \\(u_{n+1}\\)/\\(u_{n}\\) justifie la nature de la série ?","a":["3 ; divergence.","1 ; indécision.","1/3 ; convergence.","0 ; divergence."],"correct":2,"why":"Le rapport vaut (n+1)/(3n).","active":true,"family":"V2-C2-M205"},{"id":"V2-C2-M205-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Les contributions sont \\(u_n=4^n/n!\\). Quelle expression du rapport consécutif convient ?","a":["\\((n+1)/4\\), de limite +∞.","\\(4/(n+1)\\), de limite zéro.","\\(4/n!\\), de limite zéro.","\\(4\\), de limite 4."],"correct":1,"why":"Factoriser (n+1)!=(n+1)n!.","active":true,"family":"V2-C2-M205"},{"id":"V2-C2-M205-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(u_n=n^2/5^n\\), un étudiant retient le rapport 5. Quelle correction donne la limite correcte ?","a":["\\(u_{n+1}/u_n=(n+1)^2/(5n^2)\\to1/5\\).","\\(u_{n+1}/u_n=5(n+1)^2/n^2\\to5\\).","\\(u_{n+1}/u_n=1/n^2\\to0\\).","\\(u_{n+1}/u_n=1\\) pour tout n."],"correct":0,"why":"La puissance au dénominateur introduit 1/5.","active":true,"family":"V2-C2-M205"},{"id":"V2-C2-M206-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(u_n=(2n/(3n+1))^n\\). Quelle limite de racine n-ième détermine sa nature ?","a":["2/3 ; convergence.","3/2 ; divergence.","1 ; indécision.","0 ; convergence."],"correct":0,"why":"La racine n-ième est 2n/(3n+1).","active":true,"family":"V2-C2-M206"},{"id":"V2-C2-M206-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(u_n=((n+1)/(2n))^n\\), quelle nature de la série est obtenue par Cauchy ?","a":["Divergente, car la racine tend vers 2.","Divergente, car le terme initial vaut 1.","Indéterminée, car n apparaît dans la puissance.","Convergente, car la racine tend vers 1/2."],"correct":3,"why":"Le quotient (n+1)/(2n) tend vers 1/2.","active":true,"family":"V2-C2-M206"},{"id":"V2-C2-M206-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une série a pour terme \\(u_n=((4n+1)/(3n))^n\\). Quelle conclusion donne la racine n-ième ?","a":["Convergence, car la limite vaut 3/4.","Convergence, car le quotient est borné.","Divergence, car la limite vaut 4/3.","Indécision, car la limite vaut 1."],"correct":2,"why":"La limite 4/3 est supérieure à un.","active":true,"family":"V2-C2-M206"},{"id":"V2-C2-M207-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une série possède \\(u_n=1/(n(n+1))\\). Quelle expression exacte de \\(S_{N}\\) résulte de la décomposition télescopique ?","a":["\\(1-1/N\\)","\\(1-1/(N+1)\\)","\\(1/(N+1)\\)","\\(N/(N+1)^2\\)"],"correct":1,"why":"Les termes intermédiaires s'annulent entre 1 et N+1.","active":true,"family":"V2-C2-M207"},{"id":"V2-C2-M207-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(u_n=2/(n(n+1))\\), quelle quantité est cumulée au bout de trois étapes ?","a":["2.","1,5.","1/2.","3/2+2."],"correct":1,"why":"\\(S_{3}\\)=2(1-1/4)=1,5.","active":true,"family":"V2-C2-M207"},{"id":"V2-C2-M207-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"On obtient \\(S_{N}\\)=5-5/(N+1) pour une série d'apports. Quel cumul théorique et quel comportement des sommes partielles sont corrects ?","a":["5 ; elles croissent vers 5.","5 ; elles décroissent vers 5.","0 ; elles décroissent vers zéro.","+∞ ; elles croissent sans borne."],"correct":0,"why":"Le terme retranché tend vers zéro en décroissant.","active":true,"family":"V2-C2-M207"},{"id":"V2-C2-M208-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(\\sum_{n=1}^{\\infty}1/n^{3/2}\\), quelle justification est suffisante ?","a":["Riemann avec p=3/2<1 : divergence.","Le terme général tend vers zéro : preuve suffisante.","D'Alembert donne une limite nulle.","Riemann avec p=3/2>1 : convergence."],"correct":3,"why":"L'exposant est strictement supérieur à un.","active":true,"family":"V2-C2-M208"},{"id":"V2-C2-M208-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une modélisation donne des termes \\(u_n=1/\\sqrt n\\). Quelle conclusion est exacte ?","a":["Elle converge, car \\(u_{n}\\) tend vers zéro.","Elle converge, car p=2.","La série diverge, car p=1/2.","La somme vaut 1."],"correct":2,"why":"Le critère de Riemann exige p>1.","active":true,"family":"V2-C2-M208"},{"id":"V2-C2-M208-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(u_n=1/n^{1,1}\\), un étudiant conclut à la divergence car l'exposant est proche de 1. Quelle est la conclusion rigoureuse ?","a":["Divergence, car l'exposant est inférieur à 2.","Divergence, car les termes sont positifs.","Convergence, car l'exposant est strictement supérieur à 1.","Le critère de Riemann est indécis pour tout exposant décimal."],"correct":2,"why":"Le seuil est 1, quelle que soit la proximité.","active":true,"family":"V2-C2-M208"},{"id":"V2-C2-M209-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une réserve suit \\(V_{n+1}\\)=\\(V_{n}\\)+4, avec \\(V_{0}\\)=20 L. Quelle valeur prévoit le modèle au rang 6 ?","a":["24 L.","44 L.","40 L.","80 L."],"correct":1,"why":"\\(V_{n}\\)=20+4n.","active":true,"family":"V2-C2-M209"},{"id":"V2-C2-M209-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une suite arithmétique d'observations a \\(V_{3}\\)=32 et \\(V_{7}\\)=48. Quel accroissement par étape correspond à ces deux mesures ?","a":["4 unités.","16 unités.","8 unités.","12 unités."],"correct":0,"why":"La différence 16 est répartie sur quatre pas.","active":true,"family":"V2-C2-M209"},{"id":"V2-C2-M209-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Un modèle prévoit une diminution arithmétique de 3 L par jour depuis 40 L. Quel premier entier n donne \\(V_{n}\\)≤10 ?","a":["9.","11.","13.","10."],"correct":3,"why":"40-3n≤10 impose n≥10.","active":true,"family":"V2-C2-M209"},{"id":"V2-C2-M210-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une réserve \\(V_{0}\\)=240 L conserve les trois quarts de son volume chaque jour. Quel volume reste après deux jours ?","a":["180 L.","60 L.","120 L.","135 L."],"correct":3,"why":"240×(3/4)²=135.","active":true,"family":"V2-C2-M210"},{"id":"V2-C2-M210-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une suite géométrique de raison positive possède \\(V_{0}\\)=80 et \\(V_{2}\\)=20. Quelle est sa raison ?","a":["1/4.","2.","1/2.","4."],"correct":2,"why":"q²=20/80=1/4 et q>0.","active":true,"family":"V2-C2-M210"},{"id":"V2-C2-M210-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Un capteur relève une valeur initiale 96 divisée par deux à chaque étape. Quel premier rang donne une valeur inférieure ou égale à 12 ?","a":["2.","3.","4.","8."],"correct":1,"why":"96/2³=12.","active":true,"family":"V2-C2-M210"},{"id":"V2-C2-M211-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"On suit \\(V_{n}\\)=100-20/(n+1) L. Quelle description combine monotonie et borne ?","a":["Croissante, majorée par 100.","Décroissante, minorée par 100.","Croissante, non majorée.","Constante, égale à 80."],"correct":0,"why":"Le terme retranché décroît vers zéro.","active":true,"family":"V2-C2-M211"},{"id":"V2-C2-M211-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(u_n=n/(n+3)\\), quelle écriture démontre la convergence monotone ?","a":["\\(u_n=1-3/(n+3)\\), croissante et majorée par 1.","\\(u_n=1+3/(n+3)\\), décroissante.","\\(u_n=n/3\\), non majorée.","\\(u_n=1-3/n\\), identique pour tout n."],"correct":0,"why":"La forme 1 moins une quantité positive décroissante est croissante.","active":true,"family":"V2-C2-M211"},{"id":"V2-C2-M211-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une suite de volumes vérifie \\(V_{n}\\)=15+8/(n+1). Quelle affirmation est correcte ?","a":["Elle croît et est majorée par 15.","Elle décroît sans minorant.","Elle est constante, égale à 23.","Elle décroît et est minorée par 15."],"correct":3,"why":"Le terme positif décroît vers zéro.","active":true,"family":"V2-C2-M211"},{"id":"V2-C2-M212-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour la récurrence \\(V_{n+1}\\)=\\(V_{n}\\)/2+6, si une limite finie L existe, quelle équation doit-elle satisfaire ?","a":["\\(L=L+6\\), donc L=6.","\\(L=2L+6\\), donc L=6.","\\(L=L/2+6\\), donc L=12.","\\(L=0\\) nécessairement."],"correct":2,"why":"Passer à la limite dans la relation de récurrence.","active":true,"family":"V2-C2-M212"},{"id":"V2-C2-M212-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Un modèle de stockage vérifie \\(V_{n+1}\\)=0,8\\(V_{n}\\)+10. Quelle valeur stationnaire est compatible avec cette relation ?","a":["10.","50.","8.","12,5."],"correct":1,"why":"Résoudre L=0,8L+10.","active":true,"family":"V2-C2-M212"},{"id":"V2-C2-M212-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une récurrence \\(V_{n+1}\\)=0,6\\(V_{n}\\)+20 possède une limite finie. Un étudiant propose 20. Quelle correction est exacte ?","a":["L=20, car l'apport constant impose la limite.","L=50, car la fraction 0,6L du stock subsiste.","L=12, car on multiplie 20 par 0,6.","L=0, car toute fraction inférieure à un implique une limite nulle."],"correct":1,"why":"Résoudre 0,4L=20.","active":true,"family":"V2-C2-M212"},{"id":"V2-C2-M213-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(u_n=(4n+3)/(2n+5)\\), quelle limite se déduit du rapport des coefficients dominants ?","a":["2.","4/5.","3/5.","+∞."],"correct":0,"why":"Diviser numérateur et dénominateur par n.","active":true,"family":"V2-C2-M213"},{"id":"V2-C2-M213-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une grandeur discrète est \\(V_n=(6n^2+1)/(3n^2+4)\\). Quel niveau limite le modèle prévoit-il ?","a":["1/4.","3.","+∞.","2."],"correct":3,"why":"Les coefficients dominants sont 6 et 3.","active":true,"family":"V2-C2-M213"},{"id":"V2-C2-M213-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(u_n=(5n+2)/(n^2+1)\\), pourquoi la limite vaut-elle zéro ?","a":["Le rapport des coefficients dominants vaut 5.","Le numérateur ne dépend pas de n.","Le dénominateur est de degré supérieur au numérateur.","Le dénominateur tend vers zéro."],"correct":2,"why":"Le quotient est équivalent à 5/n.","active":true,"family":"V2-C2-M213"},{"id":"V2-C2-M214-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Soit \\(u_n=\\sqrt{n^2+6n}/n\\) pour n≥1. Quelle limite donne la factorisation de n² sous la racine ?","a":["6.","0.","1.","+∞."],"correct":2,"why":"\\(u_{n}\\)=√(1+6/n).","active":true,"family":"V2-C2-M214"},{"id":"V2-C2-M214-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une grandeur est \\(V_n=\\sqrt{4n^2+n}/n\\). Quelle valeur limite est correcte ?","a":["4.","2.","1.","0."],"correct":1,"why":"Factoriser n² puis prendre la racine de 4.","active":true,"family":"V2-C2-M214"},{"id":"V2-C2-M214-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Un étudiant simplifie \\(\\sqrt{9n^2+2n}/n\\) en 9+2/n. Quel résultat correct de la limite doit-il retenir ?","a":["3, car la racine porte aussi sur le coefficient 9.","9, car n² domine.","0, car 2/n tend vers zéro.","1, car n est simplifié."],"correct":0,"why":"L'expression vaut √(9+2/n).","active":true,"family":"V2-C2-M214"},{"id":"V2-C2-M215-V1","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Une suite vérifie \\(V_{n}\\)=20+2(-1)^n. Que montrent les sous-suites paires et impaires ?","a":["Elles tendent toutes deux vers 20.","Elles tendent vers zéro.","La suite converge parce qu'elle est bornée.","Elles tendent respectivement vers 22 et 18 ; la suite diverge."],"correct":3,"why":"Les deux sous-suites constantes ont des limites distinctes.","active":true,"family":"V2-C2-M215"},{"id":"V2-C2-M215-V2","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Pour \\(u_n=(-1)^n/(n+1)\\), quelle raison justifie sa convergence malgré les signes alternés ?","a":["Les sous-suites sont constantes.","La suite est strictement croissante.","Le module tend vers 1.","Son module tend vers zéro."],"correct":3,"why":"Par encadrement entre -1/(n+1) et 1/(n+1).","active":true,"family":"V2-C2-M215"},{"id":"V2-C2-M215-V3","chapter":2,"level":"moyen","usage":"ENTRAINEMENT","q":"Les relevés sont \\(V_{n}\\)=10+(-1)^n/n pour n≥1. Quel comportement à long terme est prévu ?","a":["Divergence entre 9 et 11.","Convergence vers zéro.","Convergence vers 10 avec des oscillations d'amplitude décroissante.","Croissance monotone vers 10."],"correct":2,"why":"Le terme alterné tend vers zéro.","active":true,"family":"V2-C2-M215"},{"id":"V2-C2-D203-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une série de corrections possède \\(u_n=n^2/2^n\\). Le rapport initial peut être supérieur à 1. Pourquoi cela n'empêche-t-il pas la convergence ?","a":["La raison initiale doit nécessairement être inférieure à 1.","Le rapport tend vers 1/2 ; seuls les rangs suffisamment grands comptent.","Le terme général croît pour tout n.","La série converge seulement si les premiers termes sont supprimés."],"correct":1,"why":"(n+1)²/(2n²)→1/2.","active":true,"family":"V2-C2-D203"},{"id":"V2-C2-D203-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(u_n=(n+1)!/4^n\\), quelle analyse du rapport montre la divergence ?","a":["\\(u_{n+1}/u_n=(n+2)/4\\to+\\infty\\).","\\(u_{n+1}/u_n=4/(n+2)\\to0\\).","Le terme général tend vers zéro car 4^n domine toujours une factorielle.","Le rapport tend vers 1, donc le critère est indécis."],"correct":0,"why":"La factorielle au numérateur produit un facteur n+2.","active":true,"family":"V2-C2-D203"},{"id":"V2-C2-D203-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(u_n=5^n/(2n)!\\). Quelle nature est obtenue à partir du rapport consécutif ?","a":["Convergence, car le rapport vaut \\(5/((2n+1)(2n+2))\\) et tend vers zéro.","Divergence, car le rapport tend vers 5.","Divergence, car 5^n augmente.","Indécision, car le rapport tend vers 1."],"correct":0,"why":"La factorielle augmente de deux facteurs à chaque rang.","active":true,"family":"V2-C2-D203"},{"id":"V2-C2-D204-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une série positive a pour terme \\(1/(n\\ln n)\\), n≥2. Quelle méthode démontre sa divergence ?","a":["D'Alembert : la limite du rapport vaut 0.","Riemann : le terme est inférieur à 1/n².","Le terme général ne tend pas vers zéro.","Critère intégral : une primitive de 1/(x ln x) est ln(ln x), non bornée."],"correct":3,"why":"L'intégrale correspondante diverge vers +∞.","active":true,"family":"V2-C2-D204"},{"id":"V2-C2-D204-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(\\sum_{n=2}^{\\infty}1/(n(\\ln n)^2)\\), quel argument correct conduit à la convergence ?","a":["Comparaison par la série harmonique divergente : divergence.","D'Alembert donne un rapport de limite 1/2.","Substitution t=ln x dans l'intégrale : on obtient une intégrale de t^-2 convergente.","Le terme tend vers zéro, ce qui suffit."],"correct":2,"why":"Le critère intégral s'applique à cette fonction positive décroissante.","active":true,"family":"V2-C2-D204"},{"id":"V2-C2-D204-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Soient \\(u_n=1/(n\\ln n)\\) et \\(v_n=1/(n(\\ln n)^3)\\), n≥2. Quelle distinction est correcte ?","a":["Les deux convergent, car ln n augmente.","La première série diverge et la seconde converge par le critère intégral.","Les deux divergent, car elles sont majorées par 1/n.","La première converge et la seconde diverge."],"correct":1,"why":"Après substitution t=ln x, les exposants deviennent 1 et 3.","active":true,"family":"V2-C2-D204"},{"id":"V2-C2-D205-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(u_n=(n^2+1)/(n^4+2)\\), quel diagnostic est justifié par équivalence ?","a":["Divergence, car le numérateur tend vers +∞.","Convergence, car \\(u_{n}\\) est équivalent à 1/n².","Convergence vers une somme exactement égale à 1.","Divergence, car \\(u_{n}\\) est équivalent à 1/n."],"correct":1,"why":"Comparer les puissances dominantes.","active":true,"family":"V2-C2-D205"},{"id":"V2-C2-D205-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Des apports suivent \\(u_n=(2n^2+3)/(n^3+5n)\\). Que vaut la limite de n \\(u_{n}\\) et quelle nature en résulte ?","a":["2 ; divergence par équivalence à 2/n.","0 ; convergence par Riemann.","2 ; convergence parce que la limite est finie.","+∞ ; divergence par terme général non nul."],"correct":0,"why":"n \\(u_{n}\\)=(2n³+3n)/(n³+5n)→2.","active":true,"family":"V2-C2-D205"},{"id":"V2-C2-D205-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(u_n=1/(\\sqrt{n^2+1}+n)\\), quelle équivalence permet de conclure ?","a":["\\(u_n\\sim1/n^2\\), donc convergence.","\\(u_n\\sim1/2\\), donc le terme ne tend pas vers zéro.","\\(u_n\\sim1/(2n^2)\\), donc convergence.","\\(u_n\\sim1/(2n)\\), donc divergence."],"correct":3,"why":"La racine est équivalente à n, et le dénominateur à 2n.","active":true,"family":"V2-C2-D205"},{"id":"V2-C2-D206-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une première infiltration de 160 L est suivie d'apports divisés par deux à chaque étape. Quelle quantité reste à apporter après les termes d'indices 0 à N ?","a":["\\(160/2^{N+1}\\) L.","\\(320/2^{N+3}\\) L.","\\(160/2^N\\) L.","160 L quel que soit N."],"correct":2,"why":"Le reste commence à 160/2^(N+1) et doit être divisé par 1/2.","active":true,"family":"V2-C2-D206"},{"id":"V2-C2-D206-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(u_n=90(1/3)^n\\), n≥0, quel plus petit N garantit que le reste après les indices 0 à N ne dépasse pas 5 L ?","a":["3.","4.","2.","1."],"correct":2,"why":"Le reste vaut 45/3^N : pour N=2 il vaut 5, donc le minimum est 2.","active":true,"family":"V2-C2-D206"},{"id":"V2-C2-D206-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle donne un total de 200 L, avec des apports géométriques de raison 0,5 à partir de l'indice zéro. Quel est le premier terme et le reste après les indices 0 à 3 ?","a":["Premier terme 200 L ; reste 12,5 L.","Premier terme 100 L ; reste 12,5 L.","Premier terme 100 L ; reste 25 L.","Premier terme 50 L ; reste 6,25 L."],"correct":1,"why":"\\(u_{0}\\)=S(1-q)=100 ; le reste vaut S q^4.","active":true,"family":"V2-C2-D206"},{"id":"V2-C2-D207-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour la série positive \\(\\sum_{n=1}^{\\infty}1/n^2\\), quelle majoration du reste après N termes est obtenue par comparaison intégrale ?","a":["\\(R_N\\le1/N\\)","\\(R_N\\le1/N^2\\)","\\(R_N\\le1/(2N^2)\\)","\\(R_N=0\\)"],"correct":0,"why":"L'intégrale de x^-2 de N à l'infini vaut 1/N.","active":true,"family":"V2-C2-D207"},{"id":"V2-C2-D207-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(\\sum_{n=1}^{\\infty}1/n^3\\), quel majorant intégral du reste après N termes est correct ?","a":["\\(1/N^3\\)","\\(1/(3N^3)\\)","\\(2/N\\)","\\(1/(2N^2)\\)"],"correct":3,"why":"Intégrer x^-3 entre N et +∞.","active":true,"family":"V2-C2-D207"},{"id":"V2-C2-D207-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Des apports ont pour terme \\(u_n=20/n^2\\) L. Quel nombre N de termes suffit pour garantir un reste au plus 0,5 L à l'aide de la borne intégrale ?","a":["20.","10.","5.","40."],"correct":3,"why":"R_N≤20/N ; imposer N≥40.","active":true,"family":"V2-C2-D207"},{"id":"V2-C2-D208-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une suite de stockage vérifie \\(V_{n+1}\\)=0,5\\(V_{n}\\)+10 et \\(V_{0}\\)=0. Quelle expression explicite est correcte ?","a":["\\(V_n=10(1-2^{-n})\\)","\\(V_n=20\\cdot2^{-n}\\)","\\(V_n=20(1-2^{-n})\\)","\\(V_n=10n\\)"],"correct":2,"why":"Le point fixe vaut 20 ; \\(V_{n}\\)-20=-20(1/2)^n.","active":true,"family":"V2-C2-D208"},{"id":"V2-C2-D208-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(V_{n+1}\\)=0,75\\(V_{n}\\)+5, \\(V_{0}\\)=40, quelle expression décrit l'écart au point fixe ?","a":["\\(V_n-20=40(3/4)^n\\)","\\(V_n-20=20(3/4)^n\\)","\\(V_n-5=35(3/4)^n\\)","\\(V_n-20=20(4/3)^n\\)"],"correct":1,"why":"Le point fixe vaut 20 et l'écart initial vaut 20.","active":true,"family":"V2-C2-D208"},{"id":"V2-C2-D208-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une réserve suit \\(V_{n+1}\\)=0,8\\(V_{n}\\)+4 et \\(V_{0}\\)=10. Quelle évolution est compatible avec la formule explicite ?","a":["Croissance vers 20, car \\(V_{n}\\)=20-10(0,8)^n.","Décroissance vers 4, car \\(V_{n}\\)=4+6(0,8)^n.","Croissance sans borne, car chaque étape ajoute 4.","Constante égale à 10."],"correct":0,"why":"Le point fixe est 20 et le terme négatif tend vers zéro.","active":true,"family":"V2-C2-D208"},{"id":"V2-C2-D209-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"On étudie \\(u_{n+1}=(u_n+6)/2\\) avec \\(u_{0}\\)=0. Quelle relation démontre simultanément la croissance et la majoration par 6 ?","a":["Si 0≤\\(u_{n}\\)≤6, alors \\(u_{n}\\)≤\\(u_{n+1}\\)≤6.","Si \\(u_{n}\\)≤6, alors \\(u_{n+1}\\)≥6.","Si \\(u_{n}\\)≥0, alors \\(u_{n+1}\\)≤\\(u_{n}\\).","Si \\(u_{n}\\)≤6, alors \\(u_{n+1}\\)=6."],"correct":0,"why":"La différence vaut (6-\\(u_{n}\\))/2 et \\(u_{n+1}\\) est une moyenne de \\(u_{n}\\) et 6.","active":true,"family":"V2-C2-D209"},{"id":"V2-C2-D209-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(u_{n+1}=\\sqrt{6+u_n}\\) avec \\(u_{0}\\)=0, quel encadrement inductif permet d'étudier la limite ?","a":["\\(0\\le u_n\\le2\\)","\\(3\\le u_n\\le6\\)","\\(u_n\\ge6\\)","\\(0\\le u_n\\le3\\)"],"correct":3,"why":"Si \\(u_{n}\\)≤3, alors √(6+\\(u_{n}\\))≤3.","active":true,"family":"V2-C2-D209"},{"id":"V2-C2-D209-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour la même forme de récurrence \\(u_{n+1}=\\sqrt{12+u_n}\\) avec \\(u_{0}\\)=0, quelle limite positive résulte de la convergence monotone ?","a":["3.","12.","4.","0."],"correct":2,"why":"Le point fixe positif satisfait L²-L-12=0, soit L=4.","active":true,"family":"V2-C2-D209"},{"id":"V2-C2-D210-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Calculer \\(\\lim_{n\\to\\infty}(\\sqrt{n^2+8n}-n)\\) en éliminant la forme ∞-∞.","a":["8.","4.","0.","+∞."],"correct":1,"why":"Le conjugué donne 8n/(√(n²+8n)+n)→4.","active":true,"family":"V2-C2-D210"},{"id":"V2-C2-D210-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle d'écart contient \\(E_n=\\sqrt{4n^2+12n}-2n\\). Quelle valeur limite correcte obtient-on ?","a":["6.","3.","12.","0."],"correct":1,"why":"\\(E_{n}\\)=12n/(√(4n²+12n)+2n)→12/4.","active":true,"family":"V2-C2-D210"},{"id":"V2-C2-D210-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(u_n=\\sqrt{n^2+10n+1}-n\\), un étudiant déduit une limite nulle de l'équivalence des deux termes. Quelle correction donne la bonne valeur ?","a":["5, par rationalisation et division par n.","0, car les deux termes sont équivalents.","10, car le coefficient de n est 10.","+∞, car la racine diverge."],"correct":0,"why":"Le quotient rationalisé tend vers 10/2.","active":true,"family":"V2-C2-D210"},{"id":"V2-C2-D211-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Calculer \\(\\lim_{n\\to\\infty}n\\ln(1+3/n)\\) à l'aide d'un équivalent usuel.","a":["0.","1.","+∞.","3."],"correct":3,"why":"ln(1+x) est équivalent à x près de zéro.","active":true,"family":"V2-C2-D211"},{"id":"V2-C2-D211-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une suite modélise \\(u_n=(1+2/n)^n\\). Quelle limite s'obtient en passant au logarithme ?","a":["\\(2e\\)","\\(1\\)","\\(e^2\\)","\\(+\\infty\\)"],"correct":2,"why":"Le logarithme vaut n ln(1+2/n)→2.","active":true,"family":"V2-C2-D211"},{"id":"V2-C2-D211-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(u_n=(1-1/(2n))^n\\), quelle limite positive découle du logarithme ?","a":["\\(e^{-2}\\)","\\(0\\)","\\(e^{-1/2}\\)","\\(1\\)"],"correct":2,"why":"Le logarithme tend vers -1/2.","active":true,"family":"V2-C2-D211"},{"id":"V2-C2-D212-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une série d'apports a pour terme \\(u_n=(3n/(5n+1))^n\\). Quel test justifie la convergence sans étudier des différences de termes ?","a":["D'Alembert, car le rapport vaut exactement 3/5 pour tout n.","Cauchy, car la racine n-ième tend vers 3/5.","Riemann, car \\(u_{n}\\) est équivalent à 1/n.","Le seul fait que \\(u_{n}\\) tend vers zéro suffit."],"correct":1,"why":"La racine n-ième simplifie immédiatement la puissance n.","active":true,"family":"V2-C2-D212"},{"id":"V2-C2-D212-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(u_n=((5n+1)/(4n+2))^n\\), quelle nature et quelle justification sont exactes ?","a":["Divergence, car la racine n-ième tend vers 5/4>1.","Convergence, car la racine tend vers 4/5.","Convergence, car la fraction est bornée.","Indécision, car les deux polynômes ont le même degré."],"correct":0,"why":"La limite du rapport des coefficients dominants dépasse 1.","active":true,"family":"V2-C2-D212"},{"id":"V2-C2-D212-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Soit \\(u_n=(n/(n+1))^{n^2}\\). Quelle conclusion découle de la limite de la racine n-ième ?","a":["Divergence, car la racine tend vers 1.","Divergence, car le terme est équivalent à 1.","Indécision, car l'exposant vaut n².","Convergence, car \\(\\sqrt[n]{u_n}=(1+1/n)^{-n}\\to e^{-1}\\)."],"correct":3,"why":"La limite e^-1 est strictement inférieure à 1.","active":true,"family":"V2-C2-D212"},{"id":"V2-C2-D213-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une suite positive vérifie \\(0\\le u_n\\le 4/n^2\\). Que peut-on garantir sur le cumul et le terme général ?","a":["La série diverge mais \\(u_{n}\\) tend vers zéro.","La série converge vers exactement 4.","\\(u_{n}\\) ne tend pas nécessairement vers zéro.","La série converge et \\(u_{n}\\) tend vers zéro."],"correct":3,"why":"Comparaison avec Riemann et encadrement du terme général.","active":true,"family":"V2-C2-D213"},{"id":"V2-C2-D213-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Deux séries positives ont des termes vérifiant \\(u_n\\ge 2/n\\) pour n assez grand. Quel comportement de la série des \\(u_{n}\\) est certain ?","a":["Convergence vers 2.","Convergence parce que le minorant tend vers zéro.","Divergence vers +∞.","Indécision du critère de comparaison."],"correct":2,"why":"La comparaison avec une série harmonique divergente donne la divergence.","active":true,"family":"V2-C2-D213"},{"id":"V2-C2-D213-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Soient \\(u_n=1/(n^2+4)\\) et \\(v_n=1/(n+4)\\). Quelle méthode distingue leurs natures sans calculer les sommes ?","a":["Comparer les deux premiers termes uniquement.","Comparer par équivalence : \\(u_{n}\\)∼1/n² converge, \\(v_{n}\\)∼1/n diverge.","Invoquer la décroissance, qui implique la convergence des deux séries.","Comparer à 1/n : les deux divergent."],"correct":1,"why":"Les exposants dominants sont différents.","active":true,"family":"V2-C2-D213"},{"id":"V2-C2-D214-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une somme géométrique représente 120 L cumulés, avec un premier apport de 30 L. Quelle raison positive est compatible avec la convergence ?","a":["0,75.","0,25.","4.","0,5."],"correct":0,"why":"S=\\(u_{0}\\)/(1-q), donc 1-q=30/120.","active":true,"family":"V2-C2-D214"},{"id":"V2-C2-D214-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une série géométrique positive a une somme 100 L et les apports suivants totalisent 60 L sans compter le premier. Quels sont le premier terme et la raison ?","a":["40 L ; q=0,6.","60 L ; q=0,4.","40 L ; q=0,4.","100 L ; q=0,6."],"correct":0,"why":"\\(u_{0}\\)=100-60=40 et la queue vaut qS.","active":true,"family":"V2-C2-D214"},{"id":"V2-C2-D214-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Un premier apport de 40 L est suivi d'apports géométriques. Pour que le cumul total ne dépasse pas 100 L, quelle borne supérieure de q≥0 est nécessaire et suffisante ?","a":["q≤0,4.","q≥0,6.","q≤1.","q≤0,6."],"correct":3,"why":"40/(1-q)≤100 impose q≤0,6, pour 0≤q<1.","active":true,"family":"V2-C2-D214"},{"id":"V2-C2-D215-V1","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Un modèle de débit cumulé a des apports \\(u_n=\\frac{60}{(n+2)(n+3)}\\), n≥1. Quel est le total et le reste après N termes ?","a":["Total 60 ; reste 60/(N+1).","Total 30 ; reste 60/(N+2).","Total 20 ; reste 60/(N+3).","Cumul divergent."],"correct":2,"why":"Décomposer en 60/(n+2)-60/(n+3), puis télescoper.","active":true,"family":"V2-C2-D215"},{"id":"V2-C2-D215-V2","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Pour \\(u_n=48/((n+1)(n+2))\\), n≥1, combien de termes au minimum faut-il pour que le reste soit au plus 4 ?","a":["12.","10.","11.","9."],"correct":1,"why":"Le reste vaut 48/(N+2), donc N+2≥12.","active":true,"family":"V2-C2-D215"},{"id":"V2-C2-D215-V3","chapter":2,"level":"difficile","usage":"ENTRAINEMENT","q":"Une série positive a des apports \\(u_n=\\frac{100}{n(n+2)}\\), n≥1. Quelle somme totale est obtenue par décomposition en éléments simples ?","a":["50.","75.","100.","150."],"correct":1,"why":"\\(u_{n}\\)=50(1/n-1/(n+2)) : la somme vaut 50(1+1/2).","active":true,"family":"V2-C2-D215"}]);
